<?php if ($preview && $write): ?><section class="rounded-panel border border-border bg-surface p-4"><h2><?= pl_e(pl_t('Review supplier bill')) ?></h2><p><?= pl_e($preview['supplier'] . ' · ' . $preview['input']['reference'] . ' · ' . $preview['input']['date']) ?></p><p><?= pl_e(pl_t('Currency {currency} · Rate {rate}', ['currency' => $preview['input']['currency'], 'rate' => $preview['rate_snapshot']['rate']])) ?></p><div class="table-wrap"><table class="table"><thead><tr><th><?= pl_e(pl_t('Received goods')) ?></th><th><?= pl_e(pl_t('Bill quantity')) ?></th><th><?= pl_e(pl_t('Net amount')) ?></th><th><?= pl_e(pl_t('Tax')) ?></th><th><?= pl_e(pl_t('Receipt carrying value')) ?></th><th><?= pl_e(pl_t('Price/rate variance')) ?></th></tr></thead><tbody><?php foreach ($preview['lines'] as $line): ?><tr><td><?= pl_e($line['description']) ?></td><td><?= pl_e($line['quantity']) ?></td><td><?= pl_e($line['net_fc']) ?></td><td><?= pl_e($line['tax']['tax_amount']) ?></td><td><?= pl_e($line['receipt_basis_base']) ?></td><td><?= pl_e($line['variance_base']) ?></td></tr><?php endforeach; ?></tbody></table></div><p><?= pl_e(pl_t('Total payable')) ?> <strong><?= pl_e($preview['input']['currency'] . ' ' . $preview['total_fc']) ?></strong> <?= pl_e(pl_t('· Purchase variance')) ?> <?= pl_e($company['currency'] . ' ' . $preview['variance_base']) ?></p><form method="post" action="<?= pl_e(pl_workflow_url('/purchasing')) ?>"><?php pl_ui_return_filters($filters); pl_starter_form($company, 'bill_confirm', ['id' => $order['id'] ?? 0, 'expected_hash' => $billConfirmInput?($billConfirmInput['expected_hash']??''):$preview['payload_hash'],'request_key'=>$billConfirmInput['request_key']??$preview['input']['idempotency_key']]); ?><p><label><input type="checkbox" name="confirmed" value="1" required <?= ($billConfirmInput['confirmed']??'')==='1'?'checked':'' ?>> <?= pl_e(pl_t('I reviewed the supplier, matched quantities, payable amount, taxes and price/rate differences.')) ?></label></p><button class="btn btn-primary"><?= pl_e(pl_t('Post supplier bill and match receipts')) ?></button><?php if ($billConfirmInput): ?><a class="btn btn-secondary" href="<?= pl_e(pl_workflow_url('/purchasing',$order?['id'=>$order['id'],'return_filters'=>$filters]:$filters)) ?>"><?= pl_e(pl_t('Reload current bill review')) ?></a><?php endif; ?></form></section><?php endif; ?>
<?php if ($write && $billRows): ?><details class="rounded-panel border border-border bg-surface p-4" <?= $order || $billInput ? 'open' : '' ?>><summary><?= pl_e(pl_t('Create supplier bill from receipts')) ?></summary><p><?= pl_e(pl_t('Enter quantities to bill below; leave unused receipt lines blank. All selected receipts must belong to the same supplier, currency and clearing account. Stock is already recorded.')) ?></p><form method="post" action="<?= pl_e(pl_workflow_url('/purchasing')) ?>"><?php pl_ui_return_filters($filters); pl_starter_form($company, 'bill_preview', ['id' => $order['id'] ?? 0,'request_key'=>$billInput['request_key']??$billInput['idempotency_key']??null]); ?><div class="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4"><?php pl_starter_select(pl_t('Supplier'), 'party_id', $supplierOptions, $billInput['party_id']??$order['party_id']??''); pl_starter_field(pl_t('Bill date'), 'date', $billInput['date']??gmdate('Y-m-d'), 'date'); pl_starter_field(pl_t('Due date'), 'due_date', $billInput['due_date']??gmdate('Y-m-d'), 'date'); pl_starter_field(pl_t('Currency'), 'currency', $billInput['currency']??$order['currency']??$company['currency']); pl_starter_field(pl_t('Supplier reference'), 'reference', $billInput['reference']??'', 'text', false); pl_starter_select(pl_t('Supplier bill prices'), 'price_mode', ['exclusive' => pl_t('Tax-exclusive: add selected tax'), 'inclusive' => pl_t('Tax-inclusive: entered price includes tax')], $billInput['price_mode']??$priceMode); pl_starter_select(pl_t('Received-but-unbilled liability account'), 'grni_account_id', $grniOptions, $billInput['grni_account_id']??$billRows[0]['grni_account_id']); pl_starter_field(pl_t('Manual bill rate to {currency}', ['currency' => $company['currency']]), 'rate', $billInput['rate']??'', 'text', false); pl_starter_select(pl_t('Purchase variance account'), 'variance_account_id', $varianceOptions, $billInput['variance_account_id']??'', false); pl_starter_select(pl_t('Currency rounding expense account'), 'rounding_account_id', $roundingOptions, $billInput['rounding_account_id']??'', false); ?></div>
<?php foreach (array_slice($billRows, 0, 100) as $i => $receipt): $billLine=$billLines[(int)$receipt['id']]??[]; ?><fieldset class="rounded-panel border border-border p-3 my-3"><legend><?= pl_e(pl_t('Receipt {id} · {description}', ['id' => $receipt['receipt_id'], 'description' => $receipt['description']])) ?></legend><p><?= pl_e(pl_t('{date} · Supplier {supplier} · Unbilled {unbilled} · Receipt cost {cost}', ['date' => $receipt['document_date'], 'supplier' => $supplierOptions[(string) $receipt['party_id']] ?? '', 'unbilled' => $receipt['unbilled_quantity'], 'cost' => $receipt['currency'] . ' ' . $receipt['unit_price']])) ?></p><?php pl_starter_hidden("lines[$i][receipt_line_id]", $receipt['id']); ?><div class="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4"><?php pl_starter_field(pl_t('Quantity on bill'), "lines[$i][quantity]", $billLine['quantity']??'', 'text', false); pl_starter_field(pl_t('Unit price on bill'), "lines[$i][unit_price]", $billLine['unit_price']??$receipt['unit_price'], 'text', false); pl_starter_select(pl_t('Input tax code'), "lines[$i][tax_code_id]", pl_starter_options($taxCodes), $billLine['tax_code_id']??'', false); ?></div></fieldset><?php endforeach; ?>
